void PageHandlerAsyncWaiter::GetAllUpdaterEvents(
    std::vector<std::string>* out_events) {
  base::RunLoop loop;
  proxy_->GetAllUpdaterEvents(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<std::string>* out_events
,
             const std::vector<std::string>& events) {*out_events = std::move(events);
            loop->Quit();
          },
          &loop,
          out_events));
  loop.Run();
}

std::vector<std::string> PageHandlerAsyncWaiter::GetAllUpdaterEvents(
    ) {
  std::vector<std::string> async_wait_result;
  GetAllUpdaterEvents(&async_wait_result);
  return async_wait_result;
}






